"""Build bounded author planning projection; no product generation."""
import hashlib, html, json, pathlib, shutil, subprocess, sys
P=pathlib.Path(__file__).resolve().parent;R=P.parents[6]
def write(n,x): (P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    prior=P.parent/'viewer-action-integration';review=P.parent/'viewer-action-review'
    for n in ('request.schema.json','response.schema.json'):shutil.copyfile(prior/n,P/n)
