    for p in (R/'AGENTS.md',P.parent/'current-state.json',R/'docs/board.json'):preserved[str(p.relative_to(R)).replace('\\','/')]=sha(p)
    write('preserved-inputs.json',preserved)
    audit={
      'premises':{'required_boolean':['trusted_local','consumer_matches','owner_present','document_matches','provider_ready','number_ready','number_accepted'],'required_u64_decimal':['observed_generation','observed_revision'],'required_strings':{'number_canonical':'strict decimal grammar, nonempty; C1 authenticity remains premise','number_error':'nonempty string; not interpreted as authority'},'delivery_change':['none','consumer','document','generation','closed','revision'],'optional':'delivery_observed_revision: strict U64 decimal; required for revision; same-revision remains existing M01 dependency failure','closed':True},
      'capability_record':{'required':['type: nonempty string (unknown remains UnsupportedAction)','scope: null or string (non-ui remains UnsupportedAction)','allowed_actions: array of exact Activate/SetToggle/SetText/SetNumber/SelectItem strings'],'optional':['asset_missing: nonempty string','target_missing: nonempty string','items_valid: exact bool','item_ids: array of strings'],'ComboBox':'items_valid and item_ids required; legitimate false remains UnsupportedAction','closed':True},
      'internal_state':'before is existing harness-owned authoritative state, not a provider input: preview_session/generation/revision/sequence/closed/mock/activation_count plus preservation sentinels. No new state ingestion API or authenticity claim.',
      'client':'request and response schemas bytewise unchanged; original request validation unchanged after new eager provider ingress.',
      'truthiness_audit':'Every p[]/p.get field and n[]/n.get field used by original model listed above. Exact bool rejects integers and strings; optional missing resource flags remain absent; empty resource IDs malformed. Closed capability actions enum; node type deliberately open compatibility string, not a claimed closed product type enum.'}
    write('observation-contract.json',audit)
    policies=[
      'All new typed ingress rules, required fields, closed records and dependency mapping are PROPOSED_PENDING_OWNER; this is not an adopted public product schema.',
      'Eager validation precedes request validation/native resolution, even for unused codec/node observations. Malformed input returns existing DependencyNotReady root, empty call trace and byte-equivalent state. Priority: premise shape/type/u64/delivery enum -> C1 strings -> capability records -> original policy.',
      'Malformed premise -> M01_NATIVE_IDENTITY; malformed codec value -> C1_CODEC; malformed capabilities -> M04_OWNER_INTEGRATION. Reuse existing response variants without schema edits; owner must approve these mappings and precedence.',
      'Well-typed false values are not malformed: existing UnauthorizedCaller, MissingBinding, DependencyNotReady, CodecRejected and UnsupportedAction preserved. Stale owner/revision, sequence conflict/overflow and delivery revision semantics unchanged.',
      'Existing restricted review PASS_DOCUMENT_SCOPE_PENDING_OWNER remains valid in its declared trusted-fixture domain. Three witnesses extend proposed document proof domain; they are not product/native failures.',
      'Trusted observation authenticity, freshness acquisition and atomic resolve/recheck/commit are premises; admission only establishes structural types. No FileCommit, ACK, persistence, domain mutation, new Port, product Skeleton or release authority.'
    ]
    spec={'module':'M03','task':'PD-P1-M03-PREP-01','candidate':'viewer-action-typed-correction','state':'PROPOSED_PENDING_OWNER','author':'/root/m03_viewer_intent_typed_packet','independent_verifier':None,'architecture':{'view_a':'Viewer fixture → typed observation ingress → existing viewer document use case → detached mock projection','view_b':'Request schema → existing request guards → native identity fixture → immutable capability fixture → C1 fixture → delivery recheck fixture → mock commit; typed ingress guards all fixture records first','ownership':'Existing authoritative content/history/saved hash remain untouched; sequence/mock are harness-owned detached preview state','transaction':'Malformed observations rejected before all calls and sequence/mock mutation; production atomicity NOT RUN','ports':'Existing proposed native identity/capability/C1 seams unchanged; no executable Port adoption'},'contracts':audit,'policies':policies,'acceptance':['All 77 prior fixtures preserve complete response/state/calls','Three diagnostics fail closed with response schema valid','Missing/type/enum/closed/precedence probes reject without mutation','796 product hashes and original artifacts preserved','HTML embedded ModuleSpec equals sidecar'],'tasks':[{'id':'M03-TYPED-DOC-01','scope':'this candidate directory only','contract':'closed typed fixture observation admission','BDD':['TYPED-1','TYPED-2','TYPED-3'],'TDD':'python -B checker.py; author document checks only','valid_RED':'NOT RUN; future separate Skeleton and behavior-failure RED required','status':'AUTHOR_DOCUMENT_PREPARED_PENDING_OWNER'}],'risks':['Owner has not adopted eager precedence or mappings','No native authenticity/atomicity proof','Bounded schema evaluator only, not full Draft2020 validation'],'product_source_authority':'M01/planning/s2-green/source-current.json: 796 hashes','HEAD':'5b709343a890503ebbe24a802e43cda5647df124','historical_HEAD':'31babe87a7ef1e40a0d4bedc523077e7a45d63ab','not_run':['product tests','native UI/IPC','build','packaging','valid RED','independent acceptance'],'module_complete':False}
    spec['acceptance'][0]='All 77 prior fixtures and 30 prior review cases preserve complete responses/states; all well-typed call traces preserved. Malformed revision early trace changes explicitly recorded in prior-trace-changes.json.'
    spec['bdd_categories']={'B1':'Applicable: original successes regression','B2':'Applicable: U64 min/max','B3':'Applicable: missing/type/enum/closed','B4':'Applicable: legitimate provider false','B5':'Applicable: malformed delivery observation','B6':'Applicable: complete unchanged state on malformed observations','B7':'Applicable document rejection before mock commit; native atomicity Deferred','B8':'Applicable original closed/overflow regression','B9':'Applicable unchanged mock/sequence; no rollback implementation','B10':'Applicable fixture seams only; real native integration Deferred','B11':'Applicable unknown node type retained as unsupported','B12':'Applicable original 77 + review 30 response/state regression'}
    write('module-spec.json',spec)
    text='<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><title>M03 Typed Observation Candidate</title><style>body{max-width:1100px;margin:40px auto;font:16px system-ui;line-height:1.6;background:#101821;color:#e0e9f3}pre{white-space:pre-wrap;background:#1d2b3a;padding:20px}a{color:#76caff}</style><h1>M03 Viewer typed observation proposal</h1><p>Yellow · PROPOSED_PENDING_OWNER · document-only · no product completion</p><p>既有 restricted review scoped PASS 保留。此提案擴充三個 provider 型別診斷的文件證明範圍；Owner 尚未採納。</p>'
    for title,value in [('Architecture',spec['architecture']),('Contracts and exact policy',{'audit':audit,'policies':policies}),('BDD / TDD / Tasks',spec['tasks']),('Acceptance',spec['acceptance']),('Risks and verification limits',{'risks':spec['risks'],'NOT RUN':spec['not_run']})]:text+='<h2>'+title+'</h2><pre>'+html.escape(json.dumps(value,ensure_ascii=False,indent=2))+'</pre>'
    text+='<p><a href="verification.json">Author verification</a> · <a href="model-results.json">Full response/state/call results</a> · <a href="before-after-diagnostics.json">Three before/after diagnostics</a> · <a href="traceability.json">Traceability</a></p><script type="application/json" id="module-spec">'+json.dumps(spec,ensure_ascii=False).replace('</','<\\/')+'</script></html>'
