    write('traceability.json',{'TYPED-1':{'requirement':'malformed provider cannot mutate detached preview','contract':'closed exact types','tests':'missing/type/enum/node/closed cases','result':'model-results.json'},'TYPED-2':{'requirement':'preserve existing legitimate semantics','contract':'77 prior complete responses/states/calls','tests':'prior/* and semantics/unknown-type; boundary/*','result':'model-results.json'},'TYPED-3':{'requirement':'deterministic early failclosed precedence','contract':'eager admission proposed','tests':'precedence/*; sequence/replay','result':'model-results.json'}})
    subprocess.run([sys.executable,'-B',str(P/'checker.py')],check=True)
    assert json.loads(text.split('<script type="application/json" id="module-spec">')[1].split('</script>')[0])==spec
    write('artifact-hashes.json',{p.name:sha(p) for p in sorted(P.iterdir()) if p.is_file() and p.name not in ('artifact-hashes.json','seal.json')})
    write('seal.json',{'status':'BOUNDED_AUTHOR_CANDIDATE_COMPLETE_PENDING_OWNER','manifest_sha256':sha(P/'artifact-hashes.json'),'independent_acceptance':'NOT RUN','module_complete':False})
